module ReactionsHelper
  def reactions_for(reactable)
    reactions = reactable.reactions

    if reactable.association(:reactions).loaded? && reactions.all? { |reaction| reaction.association(:reacter).loaded? }
      reactions
    else
      reactions.includes(:reacter)
    end
  end

  def reactions_path_for(reactable)
    if reactable.is_a?(Card)
      card_reactions_path(reactable)
    else
      card_comment_reactions_path(reactable.card, reactable)
    end
  end
